def index
  orders = current_account.orders.recent.includes(:customer, :line_items).limit(50)
  render json: orders.map { |o|
    { id: o.id, number: o.number, customer: o.customer.name, items: o.line_items.size }
  }
end

def topic_rows
  reply_counts = Reply.where(topic_id: @topics.map(&:id)).group(:topic_id).count
  @topics.map { |topic| { title: topic.title, replies: reply_counts.fetch(topic.id, 0) } }
end
